import{z as l,x as m,o as s,c as A,q as o,j as B,D as i,d as t,s as r,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"替代弹性","description":"","frontmatter":{"title":"替代弹性","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/elasticity-of-substitution.md","filePath":"econ/elasticity-of-substitution.md","lastUpdated":1791063341000}'),p={name:"econ/elasticity-of-substitution.md"};function C(g,a,d,h,c,_){const e=m("Mermaid");return s(),A("div",null,[a[2]||(a[2]=o('<h1 id="替代弹性" tabindex="-1">替代弹性 <a class="header-anchor" href="#替代弹性" aria-label="Permalink to &quot;替代弹性&quot;">​</a></h1><div class="epigraph"><p>替代弹性度量等产量的弯曲：要素比例对技术替代率变动有多敏感；规模一次齐次管的是射线，弯曲是另一刀。</p><footer>—— 据 Hicks, The Theory of Wages, 1932；Varian, Microeconomic Analysis 整理</footer></div><p><a href="/econ/homothetic-production">上一课</a>（齐次生产与欧拉定理）。钉了齐次次数与欧拉分尽，并写明：位似管等产量自相似，替代弹性可以单独规定。本课不重写 \\(k\\) 次齐次，也不把 CRS 再当锥讲一遍。<a href="/econ/production-technology">技术课</a>只把 \\(\\sigma\\) 说成「弯曲」。缺口是把弯曲写成导数：\\(\\sigma\\) 是什么，CES 怎样把它钉成常数，后课成本最小化怎样把它读成要素比例对价格比的反应。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两要素、光滑等产量。技术替代率 \\(\\mathrm{TRS}_{jk}=\\mathrm{MP}_j/\\mathrm{MP}_k\\) 已在技术课定义。沿同一等产量 \\(f(z)=q\\) 移动，投入比 \\(z_j/z_k\\) 随 TRS 变。Hicks 的替代弹性是这个对数导数：</p> \\[\\sigma_{jk}=\\frac{\\mathrm{d}\\ln(z_j/z_k)}{\\mathrm{d}\\ln\\mathrm{TRS}_{jk}}\\Big|_{f=q}. \\]<p>\\(\\sigma=0\\)：比例钉死，等产量成直角。<a href="/econ/leontief-technology">下一课</a>专写这个极点。\\(\\sigma\\to\\infty\\)：直线等产量，完全替代。Cobb–Douglas 的 \\(\\sigma=1\\)。缺口不是再画一次等产量，而是：<strong>规模与弯曲正交之后，\\(\\sigma\\) 必须能从 \\(f\\) 算出来，并且与后课的 \\(w\\) 反应是同一数字。</strong></p><p><span class="marginnote">数字实例：\\(\\sigma=1\\) 时，若工资相对资本价格上升 10%，最优劳动/资本投入比也恰好上调约 10%，两种要素的支出份额保持不变；若 \\(\\sigma=0.2\\)，同样的价格变化只撬动约 2% 的比例调整——等产量弯得厉害，要素就难换。</span></p><p>位似保证 TRS 沿射线不变，因此 \\(\\sigma\\) 可以只是「形状」的参数，不随 \\(q\\) 改。非位似时同一弯曲在不同产量上可以变，\\(\\sigma\\) 要标在哪一条等产量上。</p><h3 id="还没有价格" tabindex="-1">\\(\\sigma\\) 还没有价格 <a class="header-anchor" href="#还没有价格" aria-label="Permalink to &quot;$\\sigma$ 还没有价格&quot;">​</a></h3><p>定义写在 \\((z,\\mathrm{TRS})\\) 上，不出现 \\(w\\)。成本最小化之后，切条件把 TRS 钉成 \\(w_j/w_k\\)，于是同一 \\(\\sigma\\) 等于 \\(\\mathrm{d}\\ln(z_j/z_k)/\\mathrm{d}\\ln(w_k/w_j)\\)。本课先承认几何定义；不要把条件需求提前解完。</p><p><span class="marginnote">CES：\\(f(z)=\\bigl(\\sum_i a_i z_i^{\\rho}\\bigr)^{1/\\rho}\\)，\\(\\sigma=1/(1-\\rho)\\)。\\(\\rho\\to 0\\) 回到 Cobb–Douglas；\\(\\rho\\to-\\infty\\) 是列昂惕夫。一次齐次可以与任意 \\(\\sigma\\) 搭配——上一课的正交在这里变成可调参数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先沿等产量参数化：保持 \\(q\\)，用 TRS 当自变量，对 \\(\\ln(z_j/z_k)\\) 求导。两要素时这就是 Hicks 的 \\(\\sigma\\)。多于两要素，Allen–Uzawa 用成本函数的二阶导数定义偏替代弹性——那要等到 \\(c(w,q)\\) 进场，本课只钉两要素教具。</p><p>CES 是把 \\(\\sigma\\) 设成常数的函数族。估计或校准生产时，先选 \\(\\sigma\\)，再选规模弹性 \\(k\\)。不要用「劳动份额稳定」直接当 \\(\\sigma=1\\) 的证明：份额稳定还要位似加竞争付酬。</p><p><span class="marginnote">常见误区：「劳动份额长期稳定」常被当成 \\(\\sigma=1\\) 的铁证。实际上份额稳定还需要规模报酬不变、要素按边际产品付酬等前提同时成立，\\(\\sigma=1\\) 只是可能原因之一，不能从结论反向唯一推出参数。</span></p>',16)),(s(),B(n,null,{default:i(()=>[r(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOM%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E9%BD%90%E6%AC%A1%E6%AC%A1%E6%95%B0%20vs%20%E4%BD%8D%E4%BC%BC%E5%BD%A2%E7%8A%B6%22%5D%20--%3E%20SIG%5B%22%CF%83%EF%BC%9A%E7%AD%89%E4%BA%A7%E9%87%8F%E5%BC%AF%E6%9B%B2%22%5D%0A%20%20SIG%20--%3E%20CES%5B%22CES%EF%BC%9A%CF%83%20%E4%B8%BA%E5%B8%B8%E6%95%B0%22%5D%0A%20%20SIG%20--%3E%20LEO%5B%22%CF%83%20%E2%86%92%200%EF%BC%9A%E5%88%97%E6%98%82%E6%83%95%E5%A4%AB%22%5D%0A%20%20SIG%20--%3E%20CD%5B%22%CF%83%20%3D%201%EF%BC%9ACobb%E2%80%93Douglas%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"本课仍不把 \\(w\\) 当选择。几何 \\(\\sigma\\) 先立住；价格反应是同一数字的对偶面，成本课才用。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"为什么弯曲叫「替代」：TRS 是沿等产量用 \\(j\\) 换 \\(k\\) 的技术比率。等产量越弯，同一 TRS 变动只能撬动很小的比例调整——要素彼此更难替换。直线等产量上，TRS 一超过价格比（后课），厂商跳到只用一种要素；\\(\\sigma=\\infty\\) 就是这种刀刃。",-1)),(s(),B(n,null,{default:i(()=>[r(e,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E8%A6%81%E7%B4%A0%20k%20%E7%9B%B8%E5%AF%B9%E5%8F%98%E8%B4%B5%EF%BC%9A%E4%BB%B7%E6%A0%BC%E6%AF%94%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20Q%7B%22%E7%AD%89%E4%BA%A7%E9%87%8F%E6%9C%89%E5%A4%9A%E5%BC%AF%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%CF%83%20%E5%A4%A7%EF%BC%8C%E8%BF%91%E4%B9%8E%E7%9B%B4%E7%BA%BF%22%7C%20BIG%5B%22%E6%8A%95%E5%85%A5%E6%AF%94%E5%A4%A7%E5%B9%85%E8%B0%83%E6%95%B4%EF%BC%9A%E6%94%B9%E7%94%A8%E5%A4%A7%E9%87%8F%20j%22%5D%0A%20%20Q%20--%3E%7C%22%CF%83%20%3D%201%EF%BC%8CCobb%E2%80%93Douglas%22%7C%20MID%5B%22%E6%AF%94%E4%BE%8B%E5%90%8C%E5%B9%85%E8%B0%83%E6%95%B4%EF%BC%9A%E6%94%AF%E5%87%BA%E4%BB%BD%E9%A2%9D%E4%B8%8D%E5%8F%98%22%5D%0A%20%20Q%20--%3E%7C%22%CF%83%20%E2%86%92%200%EF%BC%8C%E7%9B%B4%E8%A7%92%22%7C%20ZERO%5B%22%E6%AF%94%E4%BE%8B%E7%BA%B9%E4%B8%9D%E4%B8%8D%E5%8A%A8%EF%BC%9A%E4%B8%A4%E7%A7%8D%E9%83%BD%E5%BF%85%E9%A1%BB%E7%94%A8%22%5D%0A%20%20BIG%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%20%CF%83%20%E5%9C%A8%E6%88%90%E6%9C%AC%E8%AF%BE%E8%AF%BB%E4%BD%9C%E6%AF%94%E4%BE%8B%E5%AF%B9%E4%BB%B7%E6%A0%BC%E6%AF%94%E7%9A%84%E5%BC%B9%E6%80%A7%22%5D%0A%20%20MID%20--%3E%20SAME%0A%20%20ZERO%20--%3E%20SAME%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">直觉类比：把两种要素想成零件。\\(\\sigma\\to\\infty\\) 是标准件，哪个便宜就整批换用哪个；\\(\\sigma\\to 0\\) 是左脚鞋配右脚鞋，任一边涨价都只能照买，比例永远 1:1。等产量的弯曲，量的是这对零件「好不好换」。</span></p><p>与欧拉分尽的分工：一次齐次回答「按边际付酬能否分尽 \\(q\\)」；\\(\\sigma\\) 回答「要素相对变贵时，沿等产量能换多少」。Cobb–Douglas 两者同时漂亮（\\(\\sigma=1\\) 且常取 \\(k=1\\)），不代表二者是一件事。</p><p><span class="marginnote">Hicks 1932 的 \\(\\sigma\\) 为两要素。Allen 1938、Uzawa 1962 把它接到成本函数。Varian 的教具先写等产量定义，再在成本最小化后改写成价格弹性——本课停在前一半。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不可微、折拐等产量上 \\(\\sigma\\) 不是函数，要用超微分区间。多于两要素，两两 Hicks \\(\\sigma\\) 不能任意指定，Allen–Uzawa 矩阵还有负半定约束。资本体现的技术进步会改有效投入比，看起来像 \\(\\sigma\\) 在变，其实是 \\(f\\) 在移。</p><p>也不要把 \\(\\sigma\\) 写成宏观「资本–劳动替代」的时间序列结论：那是后课加数据。本课只给生产集语言里的定义。</p><p>后课默认：两要素 \\(\\sigma\\) 是等产量上投入比对 TRS 的弹性；CES 把它钉成常数；\\(\\sigma=0\\) 下一课单独处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\sigma\\) 是沿等产量的 \\(\\mathrm{d}\\ln(z_j/z_k)/\\mathrm{d}\\ln\\mathrm{TRS}\\)，度量弯曲，不是规模。</li><li>位似让形状与 \\(q\\) 脱钩；CES 把 \\(\\sigma\\) 做成参数。</li><li>成本最小化之后，同一 \\(\\sigma\\) 读成要素比对价格比的弹性。</li><li>下一课取 \\(\\sigma=0\\)，等产量变成直角。</li><li>出处：Hicks, <em>The Theory of Wages</em>, 1932；Varian, <em>Microeconomic Analysis</em>。</li></ul>',9))])}const u=l(p,[["render",C]]);export{f as __pageData,u as default};
